 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 1, 6)}
    # The marked shape is the color other than the two background colors.
    if not colors:
        colors = {v for row in grid for v in row if v not in (0, 1)}
    mark = max(colors)
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == mark]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = mark
    return out
